internal static class PsicologiaChecks {
 public static async Task RunAsync(Action<bool,string> check){
  await using var db=new MKSANContext(new DbContextOptionsBuilder<MKSANContext>().UseInMemoryDatabase("psi-"+Guid.NewGuid()).ConfigureWarnings(w=>w.Ignore(InMemoryEventId.TransactionIgnoredWarning)).Options);
  var clock=new ClinicaClock();var journey=new JornadaService(db,clock);var service=new PsicologiaService(db,clock);
  var p=new Paciente{Id=1,UsuarioId="p",Nome="Paciente fictício",Cpf="52998224725",DataNascimento=new(2000,1,1)};var m=new Psicologo{Id=1,UsuarioId="m",Nome="Psicóloga fictícia",Crm="CRM-LEGADO",EspecialidadeId=1};var c=new Consulta{Id=1,Paciente=p,Medico=m,Data=clock.Hoje,Horario="11:00"};db.Pacientes.Add(p);db.Psicologos.Add(m);db.Especialidades.Add(new(){Id=1,Nome="Psicologia clínica"});db.Consultas.Add(c);await db.SaveChangesAsync();
  check(m.Crp==null&&!m.HabilitadoClinicamente&&db.Model.FindEntityType(typeof(Psicologo))?.GetTableName()=="Medicos","Domínio Psicologo preserva tabela e CRM sem converter registro profissional");
  check(CrpRegistro.TryNormalizar("CRP 1 / 12345",out var crp)&&crp=="01/12345"&&!CrpRegistro.TryNormalizar("CRM123",out _)&&!CrpRegistro.TryNormalizar("00/12345",out _)&&!CrpRegistro.TryNormalizar("12/00000",out _),"CRP normaliza regional e rejeita formatos e registros inválidos");
  check(PortaisAcesso.Obter("medico")==PortaisAcesso.Psicologo&&PortaisAcesso.Psicologo.Papel=="Psicologo"&&JornadaChecks.User("m","Psicologo").IsProfissionalSaude(),"Portal canônico de psicologia mantém alias de acesso legado");
  check(await service.ImpedimentoAsync(c,default)!=null,"CRM legado não habilita o atendimento psicológico");m.Crp="12/12345";check(await service.ImpedimentoAsync(c,default)!=null,"Informar CRP sem verificação não habilita atendimento");m.RegistroVerificadoEm=DateTime.UtcNow;check(await service.ImpedimentoAsync(c,default)==null,"CRP verificado habilita profissional com paciente adulto");p.DataNascimento=clock.Hoje.AddYears(-15);check(await service.ImpedimentoAsync(c,default)!=null,"Paciente menor depende da autorização conferida pelo psicólogo");
  var a=new AutorizacaoResponsavel{PacienteId=1,PsicologoId=1,Nome="Responsável fictício",Vinculo="Responsável legal",Referencia="TESTE",VerificadaPor="m",ValidaAte=DateTime.UtcNow.AddDays(1)};db.AutorizacoesResponsaveis.Add(a);await db.SaveChangesAsync();check(await service.ImpedimentoAsync(c,default)==null,"Conferência vigente do responsável permite prosseguir");a.RevogadaEm=DateTime.UtcNow;await db.SaveChangesAsync();check(await service.ImpedimentoAsync(c,default)!=null,"Revogação do responsável volta a impedir atendimento de menor");p.DataNascimento=new(2000,1,1);
  var kp=new ChaveClinica{UsuarioId="p"};var km=new ChaveClinica{UsuarioId="m"};var kf=new ChaveClinica{UsuarioId="f"};db.ChavesClinicas.AddRange(kp,km,kf);await db.SaveChangesAsync();
  string Envelope(params Guid[] ids)=>JsonSerializer.Serialize(new{versao=1,iv=Convert.ToBase64String(new byte[12]),ciphertext=Convert.ToBase64String(new byte[16]),destinatarios=ids.Select(x=>new{id=x,key=Convert.ToBase64String(new byte[384])})});
  check(await service.EnvelopeValidoAsync(Envelope(km.Id,kp.Id),"m","p",false,default),"Prontuário exige envelopes para paciente e psicólogo");check(!await service.EnvelopeValidoAsync(Envelope(km.Id),"m","p",false,default),"Prontuário não pode omitir acesso do paciente");check(await service.EnvelopeValidoAsync(Envelope(km.Id),"m","p",true,default)&&!await service.EnvelopeValidoAsync(Envelope(km.Id,kp.Id),"m","p",true,default),"Material reservado aceita somente chaves do psicólogo");check(!await service.EnvelopeValidoAsync(Envelope(km.Id,kp.Id,kf.Id),"m","p",false,default),"Recepção não pode ser destinatária de conteúdo psicológico");check(!await service.EnvelopeValidoAsync(Envelope(km.Id,km.Id),"m","p",true,default),"Envelope rejeita chave destinatária duplicada");kp.RevogadaEm=DateTime.UtcNow;await db.SaveChangesAsync();check(!await service.EnvelopeValidoAsync(Envelope(km.Id,kp.Id),"m","p",false,default),"Chave revogada não recebe novos registros");kp.RevogadaEm=null;
  var reg=new RegistroPsicologico{ConsultaId=1,PacienteId=1,PsicologoId=1,AutorUsuarioId="m",Envelope=Envelope(km.Id,kp.Id),Hash="test"};db.RegistrosPsicologicos.Add(reg);await db.SaveChangesAsync();reg.Categoria="Encerramento";var immutable=false;try{await db.SaveChangesAsync();}catch(InvalidOperationException){immutable=true;}check(immutable,"Registro publicado não pode ser sobrescrito pelo contexto");db.Entry(reg).State=EntityState.Unchanged;
  db.Psicologos.Add(new(){Id=2,UsuarioId="rt",Nome="RT fictício",Crp="12/98765",RegistroVerificadoEm=DateTime.UtcNow,ResponsavelTecnico=true,EspecialidadeId=1});db.GuardasRegistrosPsicologicos.Add(new(){RegistroId=reg.Id,PsicologoId=2,ChaveId=km.Id,ChaveCifrada="FICTICIO",ConcedidaPor="m"});await db.SaveChangesAsync();check(await db.GuardasRegistrosPsicologicos.CountAsync(g=>g.PsicologoId==2)==1,"Consulta de guarda filtra o profissional destinatário");
  var ac=new PsicologiaController(db,journey,clock){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=JornadaChecks.User("rt","Psicologo")}}};var acervoResult=(JsonResult)await ac.AcervoDados(default);using(var doc=JsonDocument.Parse(JsonSerializer.Serialize(acervoResult.Value))){check(doc.RootElement.GetProperty("registros").GetArrayLength()==1,"Responsável técnico recebe somente o acervo compartilhado");}
  var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"RENDER_EXTERNAL_URL","https://callmed.test"},{"PepIntegration:Fhir:Enabled","true"},{"PepIntegration:Fhir:BaseUrl","https://fhir.ficticio.invalid/R4"},{"PepIntegration:Fhir:BearerToken","token-FICTICIO"},{"PepIntegration:Fhir:IdentifierSystem","urn:callmed:test-psych"}}).Build();
  var factory=new FhirFactory();var fhir=new FhirPsicologiaService(db,factory,config,clock);var bundle=await fhir.BundleAsync(1,default);using(var json=JsonDocument.Parse(bundle!)){var entries=json.RootElement.GetProperty("entry").EnumerateArray().ToArray();check(entries.Length==3&&entries.All(e=>e.GetProperty("request").GetProperty("method").GetString()=="PUT"),"Adaptador produz transação FHIR com atualizações condicionais idempotentes");check(bundle!.Contains("12/12345")&&!bundle.Contains("CRM-LEGADO")&&!bundle.Contains("ciphertext")&&!bundle.Contains("52998224725"),"FHIR envia CRP e dados administrativos mínimos, sem CRM legado, CPF ou registro clínico");}
  check((await fhir.TestarAsync(default)).StartsWith("Conexão e capacidades"),"Adaptador verifica metadados e capacidades do PEP simulado");check(await fhir.EnviarAsync(1,default)&&factory.Handler.Authorization=="Bearer token-FICTICIO","Exportação usa autenticação e valida resposta da transação");factory.Handler.Partial=true;check(!await fhir.EnviarAsync(1,default),"HTTP 200 com falha dentro da transação não confirma exportação");config["PepIntegration:Fhir:Enabled"]="false";var before=factory.Handler.Calls;check(!await fhir.EnviarAsync(1,default)&&factory.Handler.Calls==before,"Adaptador desabilitado não faz chamadas externas");
  var dp=new EphemeralDataProtectionProvider();var links=new PreparacaoLinkService(dp,config);var link=links.Criar(c)!;var token=Uri.UnescapeDataString(link.Split("token=")[1]);check(links.Ler(token)?.Snapshot==JornadaService.Snapshot(c)&&links.Ler(token+"X")==null,"Link de preparação protege vínculo, revisão e validade e rejeita alteração");
  check(MKSANCrud.Services.Agendamento.AgendamentoService.Sobrepoe("10:00",50,"10:30",50)&&!MKSANCrud.Services.Agendamento.AgendamentoService.Sobrepoe("10:00",50,"10:50",50),"Agenda considera duração integral da sessão e permite horários adjacentes");
 }
 sealed class FhirFactory:IHttpClientFactory {public FhirHandler Handler{get;}=new();public HttpClient CreateClient(string name)=>new(Handler,false);}
 sealed class FhirHandler:HttpMessageHandler {public bool Partial;public int Calls;public string? Authorization;protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage req,CancellationToken ct){Calls++;Authorization=req.Headers.Authorization?.ToString();if(req.Method==HttpMethod.Get)return Json("{\"resourceType\":\"CapabilityStatement\",\"fhirVersion\":\"4.0.1\",\"rest\":[{\"mode\":\"server\",\"interaction\":[{\"code\":\"transaction\"}],\"resource\":[{\"type\":\"Patient\",\"conditionalUpdate\":true},{\"type\":\"Practitioner\",\"conditionalUpdate\":true},{\"type\":\"Appointment\",\"conditionalUpdate\":true}]}]}");_ =await req.Content!.ReadAsStringAsync(ct);return Json(JsonSerializer.Serialize(new{resourceType="Bundle",type="transaction-response",entry=new[]{new{response=new{status="200 OK"}},new{response=new{status=Partial?"412 Conflict":"201 Created"}},new{response=new{status="200 OK"}}}}));}static HttpResponseMessage Json(string body)=>new(HttpStatusCode.OK){Content=new StringContent(body,Encoding.UTF8,"application/fhir+json")};}
}
